52	 */
53	
54	@RestController
55	@CrossOrigin(exposedHeaders = "errors, content-type")
56	@RequestMapping("/api")
57	public class OwnerRestControllerV1 implements OwnersApi {
58	
59	    private final ClinicService clinicService;
60	
61	    private final OwnerMapper ownerMapper;
62	
63	    private final PetMapper petMapper;
64	
65	    private final VisitMapper visitMapper;
66	
67	    public OwnerRestControllerV1(ClinicService clinicService,
68	                                 OwnerMapper ownerMapper,
69	                                 PetMapper petMapper,
70	                                 VisitMapper visitMapper) {
71	        this.clinicService = clinicService;
72	        this.ownerMapper = ownerMapper;
73	        this.petMapper = petMapper;
74	        this.visitMapper = visitMapper;
75	    }
76	
77	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
78	    @Override
79	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
80	        Collection<Owner> owners;
81	        if (lastName != null) {
82	            owners = this.clinicService.findOwnerByLastName(lastName);
83	        } else {
84	            owners = this.clinicService.findAllOwners();
85	        }
86	        if (owners.isEmpty()) {
87	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
88	        }
89	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
90	    }
91	
92	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
93	    @Override
94	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
95	        Owner owner = this.clinicService.findOwnerById(ownerId);
96	        if (owner == null) {
97	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
98	        }
99	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
100	    }
101	
102	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
103	    @Override
104	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
105	        HttpHeaders headers = new HttpHeaders();
106	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
107	        owner.setTelephone(normalizeTelephone(owner.getTelephone()));
108	        if (isDuplicateOwner(owner) || isDuplicateEmail(owner)) {
109	            return new ResponseEntity<>(HttpStatus.CONFLICT);
110	        }
111	        if (owner.getRegistrationDate() == null) {
112	            owner.setRegistrationDate(LocalDate.now());
113	        }
114	        if (hasReachedDailyRegistrationLimit(owner.getRegistrationDate())) {
115	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
116	        }
117	        if (hasReachedCityCapacity(owner.getCity())) {
118	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
119	        }
120	        owner.setNamesakeCount(countNamesakes(owner.getLastName()));
121	        owner.setMembershipNumber(this.clinicService.findAllOwners().size() + 1);
122	        owner.setMembershipTier(determineMembershipTier(owner.getMembershipNumber()));
123	        owner.setCity(normalizeCity(owner.getCity()));
124	        owner.setCustomerCode(generateCustomerCode(owner.getCity()));
125	        this.clinicService.saveOwner(owner);
126	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
127	        headers.setLocation(UriComponentsBuilder.newInstance()
128	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
129	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
130	    }
131	
132	    /**
133	     * The maximum number of owners that may be registered on any single day.
134	     */
135	    private static final long MAX_OWNERS_PER_DAY = 20;
136	
137	    /**
138	     * Determines whether the number of owners already registered on the given date has reached the
139	     * daily registration limit. When 20 owners share the same registration date, no further owner may
140	     * be created for that day.
141	     */
142	    private boolean hasReachedDailyRegistrationLimit(LocalDate registrationDate) {
143	        long ownersRegisteredOnDate = this.clinicService.findAllOwners().stream()
144	            .filter(existing -> Objects.equals(existing.getRegistrationDate(), registrationDate))
145	            .count();
146	        return ownersRegisteredOnDate >= MAX_OWNERS_PER_DAY;
147	    }
148	
149	    /**
150	     * The maximum number of owners that may share a single city.
151	     */
152	    private static final long MAX_OWNERS_PER_CITY = 8;
153	
154	    /**
155	     * Determines whether the given city has already reached its capacity of owners. When a city
156	     * already contains 8 owners, no further owner may be created in that city. Cities are matched
157	     * ignoring letter case.
158	     */
159	    private boolean hasReachedCityCapacity(String city) {
160	        if (city == null) {
161	            return false;
162	        }
163	        long ownersInCity = this.clinicService.findAllOwners().stream()
164	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
165	            .count();
166	        return ownersInCity >= MAX_OWNERS_PER_CITY;
167	    }
168	
169	    /**
170	     * Counts how many existing owners share the given last name at the moment a new owner is
171	     * created. The newly created owner itself is not yet persisted and so is never included in
172	     * the count. Last names are compared exactly.
173	     */
174	    private int countNamesakes(String lastName) {
175	        if (lastName == null) {
176	            return 0;
177	        }
178	        return (int) this.clinicService.findAllOwners().stream()
179	            .filter(existing -> Objects.equals(existing.getLastName(), lastName))
180	            .count();
181	    }
182	
183	    /**
184	     * The number of owners that receive the founding membership tier. The first 100 owners ever
185	     * created are 'FOUNDING'; every owner created thereafter is 'STANDARD'.
186	     */
187	    private static final int FOUNDING_TIER_LIMIT = 100;
188	
189	    /**
190	     * Determines the membership tier for a newly created owner based on its sequential membership
191	     * number. Owners whose membership number is within the first {@value #FOUNDING_TIER_LIMIT} are
192	     * 'FOUNDING'; all later owners are 'STANDARD'.
193	     */
194	    private String determineMembershipTier(int membershipNumber) {
195	        return membershipNumber <= FOUNDING_TIER_LIMIT ? "FOUNDING" : "STANDARD";
196	    }
197	
198	    /**
199	     * Generates the customer code for a newly created owner. The code is formatted as
200	     * '&lt;UPPERCASE_CITY&gt;-&lt;NNNN&gt;' where NNNN is one more than the number of owners that
201	     * already exist in that city, zero-padded to four digits (for example 'LONDON-0007').
202	     * Cities are matched ignoring letter case.
203	     */
204	    private String generateCustomerCode(String city) {
205	        long ownersInCity = this.clinicService.findAllOwners().stream()
206	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
207	            .count();
208	        return String.format("%s-%04d", city.toUpperCase(Locale.ROOT), ownersInCity + 1);
209	    }
210	
211	    /**
212	     * Normalizes the city of a newly created owner. If an owner already exists in the same
213	     * city (matched ignoring letter case), that existing owner's exact spelling of the city is
214	     * reused so that all owners in a city share one canonical spelling. Otherwise the supplied
215	     * city is title-cased, capitalizing the first letter of each whitespace-separated word and
216	     * lowercasing the rest, so for example "new york" becomes "New York".
217	     */
218	    private String normalizeCity(String city) {
219	        if (city == null) {
220	            return null;
221	        }
222	        return this.clinicService.findAllOwners().stream()
223	            .map(Owner::getCity)
224	            .filter(existing -> existing != null && existing.equalsIgnoreCase(city))
225	            .findFirst()
226	            .orElseGet(() -> toTitleCase(city));
227	    }
228	
229	    /**
230	     * Title-cases the given value by capitalizing the first letter of each whitespace-separated
231	     * word and lowercasing the remaining letters, preserving the original whitespace: for example
232	     * "new  YORK" becomes "New  York".
233	     */
234	    private static String toTitleCase(String value) {
235	        StringBuilder result = new StringBuilder(value.length());
236	        boolean capitalizeNext = true;
237	        for (int i = 0; i < value.length(); i++) {
238	            char c = value.charAt(i);
239	            if (Character.isWhitespace(c)) {
240	                capitalizeNext = true;
241	                result.append(c);
242	            } else if (capitalizeNext) {
243	                result.append(Character.toTitleCase(c));
244	                capitalizeNext = false;
245	            } else {
246	                result.append(Character.toLowerCase(c));
247	            }
248	        }
249	        return result.toString();
250	    }
251	
252	    /**
253	     * Determines whether an owner already exists that uses the same telephone number
254	     * as the given one. Telephone numbers must be unique across all owners. The
255	     * comparison ignores letter case and any surrounding or repeated whitespace.
256	     */
257	    private boolean isDuplicateOwner(Owner owner) {
258	        String telephone = normalizeTelephone(owner.getTelephone());
259	        return this.clinicService.findAllOwners().stream()
260	            .anyMatch(existing -> Objects.equals(normalizeTelephone(existing.getTelephone()), telephone));
261	    }
262	
263	    /**
264	     * Normalizes a telephone number for storage and comparison by stripping spaces, dashes
265	     * and parentheses so that only digits remain: for example "(613) 555-0100" becomes
266	     * "6135550100". This lets differently punctuated forms of the same number be treated as
267	     * equal for the uniqueness check and stored in a single canonical form.
268	     */
269	    private static String normalizeTelephone(String telephone) {
270	        if (telephone == null) {
271	            return null;
272	        }
273	        return telephone.replaceAll("[\\s()-]", "");
274	    }
275	
276	    /**
277	     * Determines whether another owner already uses the same email address as the given one.
278	     * Email addresses, when supplied, must be unique across all owners. An owner without an
279	     * email address is never considered a duplicate. The comparison ignores letter case and
280	     * any surrounding or repeated whitespace.
281	     */
282	    private boolean isDuplicateEmail(Owner owner) {
283	        String email = normalize(owner.getEmail());
284	        if (email == null || email.isEmpty()) {
285	            return false;
286	        }
287	        return this.clinicService.findAllOwners().stream()
288	            .anyMatch(existing -> Objects.equals(normalize(existing.getEmail()), email));
289	    }
290	
291	    /**
292	     * Normalizes a user-supplied value for duplicate detection so that comparisons ignore
293	     * letter case and any surrounding or repeated whitespace: for example "  john   smith "
294	     * and "John Smith" normalize to the same key and so count as the same person.
295	     */
296	    private static String normalize(String value) {
297	        if (value == null) {
298	            return null;
299	        }
300	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
301	    }
302	
303	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
304	    @Override
305	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
306	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
307	        if (currentOwner == null) {
308	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
309	        }
310	        currentOwner.setAddress(ownerFieldsDto.getAddress());
311	        currentOwner.setCity(ownerFieldsDto.getCity());
312	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
313	        currentOwner.setLastName(ownerFieldsDto.getLastName());
314	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
315	        this.clinicService.saveOwner(currentOwner);
316	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
317	    }
318	
319	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
320	    @Transactional
321	    @Override
322	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
323	        Owner owner = this.clinicService.findOwnerById(ownerId);
324	        if (owner == null) {
325	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
326	        }
327	        this.clinicService.deleteOwner(owner);
328	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
329	    }
330	
331	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
332	    @Override
333	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
334	        Owner owner = this.clinicService.findOwnerById(ownerId);
335	        if (owner == null) {
336	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
337	        }
338	        HttpHeaders headers = new HttpHeaders();
339	        Pet pet = petMapper.toPet(petFieldsDto);
340	        owner.setId(ownerId);
341	        pet.setOwner(owner);
342	        pet.getType().setName(null);
343	        this.clinicService.savePet(pet);
344	        PetDto petDto = petMapper.toPetDto(pet);
345	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
346	            .buildAndExpand(pet.getId()).toUri());
347	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
348	    }
349	
350	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
351	    @Override
352	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
353	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
354	        if (currentOwner != null) {
355	            Pet currentPet = this.clinicService.findPetById(petId);
356	            if (currentPet != null) {
357	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
358	                currentPet.setName(petFieldsDto.getName());
359	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
360	                this.clinicService.savePet(currentPet);
361	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
362	            }
363	        }
364	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
365	    }
366	
367	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
368	    @Override
369	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
370	        HttpHeaders headers = new HttpHeaders();
371	        Visit visit = visitMapper.toVisit(visitFieldsDto);
372	        Pet pet = new Pet();
373	        pet.setId(petId);
374	        visit.setPet(pet);
375	        this.clinicService.saveVisit(visit);
376	        VisitDto visitDto = visitMapper.toVisitDto(visit);
377	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
378	            .buildAndExpand(visit.getId()).toUri());
379	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
380	    }
381	
382	
383	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
384	    @Override
385	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
386	        Owner owner = this.clinicService.findOwnerById(ownerId);
387	        if (owner != null) {
388	            Pet pet = owner.getPet(petId);
389	            if (pet != null) {
390	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
391	            }
392	        }
393	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
394	    }
395	}
